def serialize_response(
    *,
    field: Field = None,
    response: Response,
    include: Set[str] = None,
    exclude: Set[str] = set(),
    by_alias: bool = True,
    skip_defaults: bool = False,
) -> Any:
    if field:
        errors = []
        value, errors_ = field.validate(response, {}, loc=("response",))
        if isinstance(errors_, ErrorWrapper):
            errors.append(errors_)
        elif isinstance(errors_, list):
            errors.extend(errors_)
        if errors:
            raise ValidationError(errors)

        jsonable_data = jsonable_encoder(
            value,
            include=include,
            exclude=exclude,
            by_alias=by_alias,
            skip_defaults=skip_defaults,
        )

        # Check if `skip_defaults` is set and apply it correctly.
        if skip_defaults:
            return {k: v for k, v in jsonable_data.items() if v is not None}

        return jsonable_data
    else:
        jsonable_data = jsonable_encoder(response)

        if skip_defaults:
            return {k: v for k, v in jsonable_data.items() if v is not None}

        return jsonable_data
